css:
[data-bz-section="quote-rotator"] [data-bz-node="qr-inner"] { max-width: 900px; margin-inline: auto; text-align: center }
[data-bz-section="quote-rotator"] [data-bz-node="qr-title"] { margin-bottom: var(--space-6) }
[data-bz-section="quote-rotator"] [data-bz-node^="qr-slide"] { min-height: 150px }
[data-bz-section="quote-rotator"] [data-bz-node^="qr-quote"] p { font-size: 20px; line-height: 1.6; font-style: italic; color: var(--ink); margin: 0 0 var(--space-5) }
[data-bz-section="quote-rotator"] [data-bz-node^="qr-name"] p { font-family: var(--font-heading); font-weight: 700; font-size: var(--text-body); color: var(--ink); margin: 0 }
[data-bz-section="quote-rotator"] [data-bz-node^="qr-role"] p { font-size: var(--text-small); color: var(--muted); margin: 0 }
[data-bz-section="quote-rotator"] [data-bz-node="qr-controls"] { display: flex; align-items: center; justify-content: center; gap: var(--space-5); margin-top: var(--space-6) }
[data-bz-section="quote-rotator"] [data-bz-node="qr-controls"] > .bz-col { width: auto; flex: 0 0 auto }
[data-bz-section="quote-rotator"] [data-bz-node="qr-controls"] .bz-btns { margin-block: 0 }
[data-bz-section="quote-rotator"] [data-bz-node="qr-controls"] .bz-btn { width: 40px; height: 40px; min-height: 40px; padding: 0; overflow: hidden; text-indent: -999px; border-radius: var(--radius-chip); background: var(--card); border: 1px solid var(--line); position: relative }
[data-bz-section="quote-rotator"] [data-bz-node="qr-prev"] .bz-btn::after,
[data-bz-section="quote-rotator"] [data-bz-node="qr-next"] .bz-btn::after { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; text-indent: 0; color: var(--ink); font-size: var(--text-body) }
[data-bz-section="quote-rotator"] [data-bz-node="qr-prev"] .bz-btn::after { content: "\2039" }
[data-bz-section="quote-rotator"] [data-bz-node="qr-next"] .bz-btn::after { content: "\203A" }
[data-bz-section="quote-rotator"] [data-bz-node="qr-dots"] { display: flex; gap: var(--space-2); align-items: center }
[data-bz-section="quote-rotator"] .bz-dot { width: 8px; height: 8px; padding: 0; border: 0; border-radius: var(--radius-chip); background: var(--line); cursor: pointer }
[data-bz-section="quote-rotator"] .bz-dot[aria-current="true"] { background: var(--accent-dark) }
